// Local bridge for the blockout editor's "Generate draft" flow (the editor page cannot write files through python http.server).
//   node bridge.mjs            -> http://127.0.0.1:5812
// It ONLY reads and writes small files inside ./drafts/<id>/ of this project and serves result videos from there.
// With a Tein key saved it can send a draft, finalize it and make Seedream 5.5 reference pictures itself (each costs money on that Tein account). The key stays in the macOS Keychain.
// The user's own Claude agent can do the same steps instead (see DRAFT-FLOW.md). The two /dev-* endpoints are placeholders for testing the flow without Claude and without cost.
import http from 'node:http';
import crypto from 'node:crypto';
import { pickFrames } from './tools/frames-pick.mjs';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import os from 'node:os';
import { spawn, spawnSync } from 'node:child_process';

const ROOT = path.dirname(fileURLToPath(import.meta.url)), DRAFTS = path.join(ROOT, 'drafts'), PORT = Number(process.env.BRIDGE_PORT || process.env.PORT || 5812);   // BRIDGE_PORT=5822 node bridge.mjs (npm start passes it on and tells the pages)
const DEV_PROMPT = path.join(ROOT, 'seedance', 'prompt.txt'), DEV_RESULT = path.join(ROOT, 'seedance', 'street-pov-draft4-neutral.mp4');
const ALLOW = /^http:\/\/(localhost|127\.0\.0\.1):\d+$/;
