const LOCAL_HOST = /^(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$/i;
// ---- SWITCHES (development and tests only; a normal start has both on).
//   TEIN_NETWORK=0  no call to Tein at all, except the public price list (TEIN_PRICING=0 stops that too)
//   TEIN_SEND=0     no paid call (send, finalize, Seedream pictures); the key test and every dry run still work
const NET = process.env.TEIN_NETWORK !== '0', SEND = NET && process.env.TEIN_SEND !== '0', TEIN = 'https://api.tein.ai', MODEL = 'seedance-2-5';

