  direct_api_not_enabled: 'Direct API calls are not enabled for this workspace.', account_suspended: 'The Tein account is suspended.', workspace_paused: 'The Tein workspace is paused.', role_cannot_run: 'This account role cannot run jobs.', creative_mode_restricted: 'Creative mode is not available for this workspace.',
