  content_blocked: 'Blocked by content moderation. Nothing was charged.', face_detected: 'A reference shows a real face. Nothing was charged.', copyright_blocked: 'Refused for copyright. Nothing was charged.', task_type_mismatch: 'The inputs do not fit this task. Nothing was charged.', invalid_input: 'Tein could not read the reference video. Nothing was charged.',
