const setStatus = (id, o) => fs.writeFileSync(path.join(DRAFTS, id, 'status.json'), JSON.stringify({ ...o, at: new Date().toISOString() }, null, 1));
const dig = (o, re, depth = 0) => { if (!o || typeof o !== 'object' || depth > 6) return null; for (const k of Object.keys(o)) if (re.test(k) && typeof o[k] === 'string' && o[k]) return o[k]; for (const k of Object.keys(o)) { const v = dig(o[k], re, depth + 1); if (v) return v; } return null; };
async function tein(pathname, key, init = {}) { if (!NET) throw new Error('network is switched off'); const r = await fetch(TEIN + pathname, { ...init, headers: { ...(init.headers || {}), ...(key ? { authorization: 'Bearer ' + key } : {}) } }); const j = await r.json().catch(() => ({})); return { status: r.status, ok: r.ok, json: j, retry: Number(r.headers.get('retry-after')) || 0 }; }
