async function waitMcp(id, key, session, requestId, outName, extra) { for (let i = 0; i < 360; i++) { await new Promise((ok) => setTimeout(ok, 10000)); const j = await mcpCall('get_generation_status', { request_id: requestId }, key, session), st = dig(j, /^status$/i) || mdf(j, 'status') || ''; setStatus(id, { step: 'wait', text: 'Seedance 2.5 is making the video (' + (st || 'waiting') + ')', job: requestId });
    if (/succeed|complete/i.test(st)) return finishJob(id, dig(j.data || j.output || j, /url$/i) || mdf(j, 'video'), { ...extra, status: st, cost: j.usage ? j.usage.cost : mdf(j, 'cost') != null ? +mdf(j, 'cost') : undefined }, outName); if (/fail|expire|cancel/i.test(st)) { const e = j.error || {}; throw new Error(plain(e.code, e.message || st)); } } throw new Error('Gave up waiting after an hour.'); }
