// Finalize: the same take at 1080p. Uses the draft's job id; only model, finalize, resolution (and the idempotency key) are sent.
// resolution: '1080p' or '4k' (Tein's value for 4K). The result is result-1080p.mp4 or result-4k.mp4; job.json keeps finalize_resolution.
const FIN = { '1080p': { file: 'result-1080p.mp4', label: '1080p' }, '4k': { file: 'result-4k.mp4', label: '4K' } };
